+        });
+        add(nameField);
+
+        emailField = new EmailField("Email");
+        emailField.setValueChangeMode(com.vaadin.flow.data.value.ValueChangeMode.EAGER);
+        emailField.addValueChangeListener(e -> {
+            hasBeenModifiedSinceSend = true;
+            sendButton.setEnabled(true);
+        });
+        add(emailField);
+
+        phoneField = new TextField("Phone");
+        phoneField.setValueChangeMode(com.vaadin.flow.data.value.ValueChangeMode.EAGER);
+        phoneField.addValueChangeListener(e -> {
+            hasBeenModifiedSinceSend = true;
+            sendButton.setEnabled(true);
+        });
+        add(phoneField);
+
+        messageField = new TextArea("Message");
+        messageField.setValueChangeMode(com.vaadin.flow.data.value.ValueChangeMode.EAGER);
+        messageField.addValueChangeListener(e -> {
+            hasBeenModifiedSinceSend = true;
+            sendButton.setEnabled(true);
+        });
+        add(messageField);
+
+        add(sendButton);
+
+        grid = new Grid<>(Message.class, false);
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getMessage).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void handleSend() {
+        clearErrors();
+
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String messageText = messageField.getValue();
+
+        boolean isValid = true;
+
+        if (name.isBlank()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (!email.isBlank() && !isValidEmail(email)) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (email.isBlank() && phone.isBlank()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (messageText.isBlank()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (messageText.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (!isValid) {
+            return;
+        }
+
+        Message message = new Message(name, email, phone, messageText);
