+
+        Notification.show("Message sent");
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+
+        sendButton.setEnabled(false);
+        hasBeenModifiedSinceSend = false;
+
+        refreshGrid();
+    }
+
+    private void clearErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private boolean isValidEmail(String email) {
+        String emailRegex = "^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$";
+        return Pattern.matches(emailRegex, email);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getMessages());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedData()) {
+            event.postpone();
+            showConfirmDialog(event);
+        }
+    }
+
+    private boolean hasUnsavedData() {
+        return !nameField.getValue().isBlank() ||
+               !emailField.getValue().isBlank() ||
+               !phoneField.getValue().isBlank() ||
+               !messageField.getValue().isBlank();
+    }
+
+    private void showConfirmDialog(BeforeLeaveEvent event) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsaved changes");
+
+        Button keepEditingButton = new Button("Keep editing", e -> dialog.close());
+        Button discardButton = new Button("Discard", e -> {
+            dialog.close();
+            event.forwardTo(event.getLocation().getPath());
+        });
+
+        dialog.getFooter().add(keepEditingButton, discardButton);
+        dialog.open();
+    }
+}
